mapper.select:
select con.Con_Code as conCode, con.Con_Name as conName, sr.Sc_Name as masterConName, sr.Sc_Code as masterConCode,
c1.C_Name_History as scFpNameHistory, c2.C_Name_History as scSpNameHistory, c1.C_Name as scFpName, c2.C_Name as scSpName, c1.C_Abbreviation as scFpAbbName, c2.C_Abbreviation as scSpAbbName, mn.* from Subcontract_Record mn
left join Con_Contract con on mn.Con_Id=con.Con_Id left join Subcontract_Record sr on mn.Sc_Master_Con_Id=sr.Sc_Id left join SYS_Company c1 on mn.Sc_Fp=c1.C_Id left join SYS_Company c2 on mn.Sc_Sp=c2.C_Id
${params.authSql}
where 1=1
and mn.Te_Id = #{params.teId}
and mn.P_Id=#{params.pId}
and mn.Sc_Fp = #{params.scFp}
and mn.Sc_Sp = #{params.scSp}
and mn.Sc_Mode = #{params.scMode}
and mn.Con_Id = #{params.conId}
and mn.Sc_State = #{params.scState}
and con.Con_Name like concat('%',#{params.conName},'%')
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and mn.Sc_Title like concat('%',#{params.scTitle},'%')
and mn.Sc_Name like concat('%',#{params.scName},'%')
and mn.Sc_Code like concat('%',#{params.scCode},'%')
and mn.Sc_Resident like concat('%',#{params.scResident},'%')
and mn.Sc_Resident_Tel like concat('%',#{params.scResidentTel},'%')
and mn.Sc_Resident_Ssn like concat('%',#{params.scResidentSsn},'%')
and mn.Sc_Id not in
#{conType}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Sc_Create_Time desc
